     "findRegex": "/<update(?:variable)?>(?!.*<\\/update(?:variable)?>)\\s*(.*)\\s*$/gsi",
     "replaceString": "<div style=\"width: 80%; margin: 20px auto;\">\n  <details class=\"night-sky-thinking\" style=\"\n    background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%);\n    border: 1px solid rgba(148, 163, 184, 0.2);\n    border-radius: 18px;\n    box-shadow: 0 4px 24px rgba(59, 130, 246, 0.15), inset 0 1px 0 rgba(148, 163, 184, 0.1);\n    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n    overflow: hidden;\n    position: relative;\n  \">\n    <summary style=\"\n      padding: 16px 24px;\n      color: #e2e8f0;\n      cursor: pointer;\n      list-style: none;\n      font-weight: 500;\n      position: relative;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      z-index: 2;\n    \">\n      <span style=\"\n        font-size: 1.3em;\n        filter: drop-shadow(0 0 10px rgba(191, 219, 254, 0.7));\n        animation: moon-pulse 2s ease-in-out infinite;\n      \">🌙</span>\n      <span style=\"flex: 1;\">明月升起，思绪流转...</span>\n      <span style=\"font-size: 0.9em; opacity: 0.7;\">✦ ˚ ✦</span>\n      <span class=\"stars-flow\" style=\"\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 100%;\n        background: \n          radial-gradient(circle at 20% 50%, rgba(191, 219, 254, 0.15) 0%, transparent 50%),\n          radial-gradient(circle at 80% 50%, rgba(147, 197, 253, 0.1) 0%, transparent 50%);\n        animation: stars-drift 4s ease-in-out infinite;\n        pointer-events: none;\n      \"></span>\n      <span class=\"moonlight-glow\" style=\"\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 100%;\n        background: linear-gradient(\n          90deg,\n          transparent 0%,\n          rgba(224, 231, 255, 0.05) 20%,\n          rgba(191, 219, 254, 0.1) 40%,\n          rgba(147, 197, 253, 0.15) 50%,\n          rgba(191, 219, 254, 0.1) 60%,\n          rgba(224, 231, 255, 0.05) 80%,\n          transparent 100%\n        );\n        animation: moonlight-sweep 3s linear infinite;\n        transform: translateX(-100%);\n        pointer-events: none;\n      \"></span>\n    </summary>\n    <div style=\"\n      max-height: 320px;\n      overflow-y: auto;\n      padding: 14px 24px;\n      color: #cbd5e1;\n      line-height: 1.7;\n      transition: all 0.3s ease;\n      white-space: pre-wrap;\n      background: rgba(15, 23, 42, 0.3);\n    \">\n    $1\n    </div>\n  </details>\n</div>\n\n<style>\n  .night-sky-thinking::-webkit-scrollbar {\n    width: 6px;\n  }\n  .night-sky-thinking::-webkit-scrollbar-track {\n    background: #0f172a;\n  }\n  .night-sky-thinking::-webkit-scrollbar-thumb {\n    background: rgba(148, 163, 184, 0.3);\n    border-radius: 3px;\n  }\n  .night-sky-thinking::-webkit-scrollbar-thumb:hover {\n    background: rgba(148, 163, 184, 0.5);\n  }\n\n  .night-sky-thinking[open] {\n    box-shadow: \n      0 8px 40px rgba(59, 130, 246, 0.25),\n      inset 0 1px 0 rgba(148, 163, 184, 0.15) !important;\n    border-color: rgba(148, 163, 184, 0.35) !important;\n  }\n  .night-sky-thinking[open] > div {\n    animation: contentFadeIn 0.4s ease forwards;\n  }\n  .night-sky-thinking[open] summary .moonlight-glow {\n    animation: none !important;\n    opacity: 0;\n  }\n\n  .night-sky-thinking summary:hover {\n    background: rgba(59, 130, 246, 0.06);\n  }\n  .night-sky-thinking[open] summary {\n    border-bottom: 1px solid rgba(148, 163, 184, 0.2);\n    background: rgba(15, 23, 42, 0.4);\n  }\n  .night-sky-thinking summary::marker {\n    display: none;\n  }\n\n  @keyframes moon-pulse {\n    0%, 100% {\n      transform: scale(1);\n      filter: drop-shadow(0 0 10px rgba(191, 219, 254, 0.7));\n    }\n    50% {\n      transform: scale(1.1);\n      filter: drop-shadow(0 0 16px rgba(191, 219, 254, 0.9));\n    }\n  }\n\n  @keyframes moonlight-sweep {\n    0% {\n      transform: translateX(-100%);\n    }\n    100% {\n      transform: translateX(100%);\n    }\n  }\n\n  @keyframes stars-drift {\n    0%, 100% {\n      opacity: 0.3;\n      transform: translateX(0);\n    }\n    50% {\n      opacity: 0.6;\n      transform: translateX(10px);\n    }\n  }\n\n  @keyframes contentFadeIn {\n    from {\n      opacity: 0;\n      transform: translateY(-10px);\n    }\n    to {\n      opacity: 1;\n      transform: translateY(0);\n    }\n  }\n</style>",
